import java.io.*;
import java.util.*;

/*
 * Family tree statements
 *
 * We parse one or more datasets. Each dataset:
 *   - starts with an integer n : number of lines in the indented family tree
 *   - then n lines, each containing a name prefixed by spaces indicating depth
 *   - then an integer q : number of statements
 *   - then q statements to evaluate
 *
 * For each statement output True / False.
 *
 * Supported statements (case-sensitive names, lowercase relation words):
 *   A is parent of B
 *   A is child of B
 *   A is sibling of B
 *   A is ancestor of B
 *   A is descendant of B
 *
 * Datasets continue until EOF.
 *
 * Notes:
 * - Indentation depth is determined by the number of leading spaces.
 * - A line with greater indentation than the previous line becomes a child of the
 *   nearest previous line with smaller indentation.
 * - Names are assumed unique within a dataset.
 */
public class Main {
    static class Person {
        String name;
        int parent = -1;
        List<Integer> children = new ArrayList<>();
        int depth;
        Person(String name) { this.name = name; }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        StringBuilder out = new StringBuilder();

        while (true) {
            line = nextNonEmptyLine(br);
            if (line == null) break;

            int n;
            try {
                n = Integer.parseInt(line.trim());
            } catch (Exception e) {
                // If input format differs unexpectedly, stop gracefully.
                break;
            }

            List<String> treeLines = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                String s = br.readLine();
                if (s == null) s = "";
                treeLines.add(s);
            }

            Family family = buildFamily(treeLines);

            String qLine = nextNonEmptyLine(br);
            if (qLine == null) break;
            int q = Integer.parseInt(qLine.trim());

            for (int i = 0; i < q; i++) {
                String stmt = br.readLine();
                if (stmt == null) stmt = "";
                boolean ans = family.evaluate(stmt);
                out.append(ans ? "True" : "False").append('\n');
            }
        }

        System.out.print(out.toString());
    }

    static String nextNonEmptyLine(BufferedReader br) throws IOException {
        String s;
        while ((s = br.readLine()) != null) {
            if (s.length() == 0) continue;
            return s;
        }
        return null;
    }

    static class Family {
        List<Person> people = new ArrayList<>();
        Map<String, Integer> id = new HashMap<>();

        int getId(String name) {
            Integer v = id.get(name);
            return v == null ? -1 : v;
        }

        boolean isParent(int a, int b) {
            return a >= 0 && b >= 0 && people.get(b).parent == a;
        }

        boolean isChild(int a, int b) {
            return isParent(b, a);
        }

        boolean isSibling(int a, int b) {
            if (a < 0 || b < 0 || a == b) return false;
            int pa = people.get(a).parent;
            int pb = people.get(b).parent;
            return pa != -1 && pa == pb;
        }

        boolean isAncestor(int a, int b) {
            if (a < 0 || b < 0 || a == b) return false;
            int cur = people.get(b).parent;
            while (cur != -1) {
                if (cur == a) return true;
                cur = people.get(cur).parent;
            }
            return false;
        }

        boolean isDescendant(int a, int b) {
            return isAncestor(b, a);
        }

        boolean evaluate(String stmt) {
            // Expected form:
            // <name1> is <relation> of <name2>
            int p = stmt.indexOf(" is ");
            if (p < 0) return false;
            String name1 = stmt.substring(0, p);
            String rest = stmt.substring(p + 4);

            int q = rest.lastIndexOf(" of ");
            if (q < 0) return false;
            String relation = rest.substring(0, q);
            String name2 = rest.substring(q + 4);

            int a = getId(name1);
            int b = getId(name2);
            if (a == -1 || b == -1) return false;

            switch (relation) {
                case "parent":
                    return isParent(a, b);
                case "child":
                    return isChild(a, b);
                case "sibling":
                    return isSibling(a, b);
                case "ancestor":
                    return isAncestor(a, b);
                case "descendant":
                    return isDescendant(a, b);
                default:
                    return false;
            }
        }
    }

    static Family buildFamily(List<String> lines) {
        Family fam = new Family();
        Deque<int[]> stack = new ArrayDeque<>(); // [indent, id]

        for (String raw : lines) {
            int indent = 0;
            while (indent < raw.length() && raw.charAt(indent) == ' ') indent++;
            String name = raw.substring(indent);

            int curId = fam.people.size();
            Person p = new Person(name);
            p.depth = indent;
            fam.people.add(p);
            fam.id.put(name, curId);

            while (!stack.isEmpty() && stack.peek()[0] >= indent) {
                stack.pop();
            }

            if (!stack.isEmpty()) {
                int parentId = stack.peek()[1];
                p.parent = parentId;
                fam.people.get(parentId).children.add(curId);
            }

            stack.push(new int[]{indent, curId});
        }

        return fam;
    }
}

