#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAXN 2005
#define MAXNAME 128
#define MAXLINE 512

typedef struct {
    char name[MAXNAME];
    int parent;
    int depth;
} Person;

static Person people[MAXN];
static int npeople;

static char queryLines[1005][MAXLINE];
static int qcount;

static void trim_newline(char *s) {
    int n = (int)strlen(s);
    while (n > 0 && (s[n-1] == '\n' || s[n-1] == '\r')) {
        s[n-1] = '\0';
        n--;
    }
}

static int leading_spaces(const char *s) {
    int i = 0;
    while (s[i] == ' ') i++;
    return i;
}

static void extract_name_from_tree_line(const char *line, char *out) {
    int i = leading_spaces(line);
    while (*line && i--) line++;
    strcpy(out, line);
}

static int find_person(const char *name) {
    for (int i = 0; i < npeople; i++) {
        if (strcmp(people[i].name, name) == 0) return i;
    }
    return -1;
}

static int get_or_add_person(const char *name) {
    int id = find_person(name);
    if (id != -1) return id;
    strcpy(people[npeople].name, name);
    people[npeople].parent = -1;
    people[npeople].depth = 0;
    return npeople++;
}

static int is_ancestor(int a, int b) {
    while (b != -1) {
        if (b == a) return 1;
        b = people[b].parent;
    }
    return 0;
}

static int generations_between(int anc, int desc) {
    int d = 0;
    while (desc != -1) {
        if (desc == anc) return d;
        desc = people[desc].parent;
        d++;
    }
    return -1;
}

static int are_siblings(int a, int b) {
    return a != b && people[a].parent != -1 && people[a].parent == people[b].parent;
}

static int cousin_degree_removed(int a, int b, int *degree, int *removed) {
    int da = people[a].depth, db = people[b].depth;
    int x = a, y = b;

    while (da > db) { x = people[x].parent; da--; }
    while (db > da) { y = people[y].parent; db--; }

    while (x != -1 && y != -1 && x != y) {
        x = people[x].parent;
        y = people[y].parent;
        da--;
        db--;
    }
    if (x == -1 || y == -1) return 0;

    int lca = x;
    int distA = people[a].depth - people[lca].depth;
    int distB = people[b].depth - people[lca].depth;

    if (distA == 0 || distB == 0) return 0;   // direct ancestor/descendant
    if (distA == 1 && distB == 1) return 0;   // siblings

    int minD = distA < distB ? distA : distB;
    int maxD = distA > distB ? distA : distB;

    *degree = minD - 1;
    *removed = maxD - minD;
    return 1;
}

static int eval_query(const char *line) {
    char a[MAXNAME], b[MAXNAME], rel[256];
    a[0] = b[0] = rel[0] = '\0';

    /* Expected general form:
       <name1> is <relationship> of <name2>
       Names are single tokens in standard versions of this problem.
    */
    if (sscanf(line, "%127s is %255[^\\n] of %127s", a, rel, b) != 3) return 0;

    int ia = find_person(a);
    int ib = find_person(b);
    if (ia == -1 || ib == -1) return 0;

    if (strcmp(rel, "child") == 0) {
        return people[ia].parent == ib;
    }
    if (strcmp(rel, "parent") == 0) {
        return people[ib].parent == ia;
    }
    if (strcmp(rel, "sibling") == 0) {
        return are_siblings(ia, ib);
    }
    if (strcmp(rel, "descendant") == 0) {
        return ia != ib && is_ancestor(ib, ia);
    }
    if (strcmp(rel, "ancestor") == 0) {
        return ia != ib && is_ancestor(ia, ib);
    }

    if (strcmp(rel, "grand child") == 0 || strcmp(rel, "grandchild") == 0) {
        return generations_between(ib, ia) == 2;
    }
    if (strcmp(rel, "grand parent") == 0 || strcmp(rel, "grandparent") == 0) {
        return generations_between(ia, ib) == 2;
    }

    /* Handle great-grand ... */
    if (strstr(rel, "child") != NULL) {
        int cnt = 0;
        char tmp[256];
        strcpy(tmp, rel);
        char *tok = strtok(tmp, " ");
        while (tok) {
            if (strcmp(tok, "great") == 0) cnt++;
            tok = strtok(NULL, " ");
        }
        if (strstr(rel, "grand") != NULL) {
            return generations_between(ib, ia) == cnt + 2;
        }
    }
    if (strstr(rel, "parent") != NULL) {
        int cnt = 0;
        char tmp[256];
        strcpy(tmp, rel);
        char *tok = strtok(tmp, " ");
        while (tok) {
            if (strcmp(tok, "great") == 0) cnt++;
            tok = strtok(NULL, " ");
        }
        if (strstr(rel, "grand") != NULL) {
            return generations_between(ia, ib) == cnt + 2;
        }
    }

    /* cousin / k-th cousin / k-th cousin removed j */
    {
        int degree, removed;
        if (!cousin_degree_removed(ia, ib, &degree, &removed)) return 0;

        if (strcmp(rel, "cousin") == 0) {
            return degree == 1 && removed == 0;
        }

        int k, r;
        if (sscanf(rel, "%d cousin removed %d", &k, &r) == 2) {
            return degree == k && removed == r;
        }
        if (sscanf(rel, "%d cousin", &k) == 1) {
            return degree == k && removed == 0;
        }
    }

    return 0;
}

int main(void) {
    char line[MAXLINE];
    int firstOutput = 1;

    while (1) {
        if (!fgets(line, sizeof(line), stdin)) break;
        trim_newline(line);
        if (line[0] == '\0') continue;

        int n, q;
        if (sscanf(line, "%d %d", &n, &q) != 2) continue;
        if (n == 0 && q == 0) break;

        npeople = 0;
        int stack_ids[MAXN];
        int stack_depths[MAXN];
        int top = -1;

        for (int i = 0; i < n; i++) {
            fgets(line, sizeof(line), stdin);
            trim_newline(line);

            int sp = leading_spaces(line);
            char name[MAXNAME];
            extract_name_from_tree_line(line, name);

            int id = get_or_add_person(name);
            people[id].depth = sp;

            while (top >= 0 && stack_depths[top] >= sp) top--;

            if (top >= 0) people[id].parent = stack_ids[top];
            else people[id].parent = -1;

            top++;
            stack_ids[top] = id;
            stack_depths[top] = sp;
        }

        for (int i = 0; i < npeople; i++) {
            int d = 0, x = i;
            while (people[x].parent != -1) {
                d++;
                x = people[x].parent;
            }
            people[i].depth = d;
        }

        for (int i = 0; i < q; i++) {
            fgets(queryLines[i], sizeof(queryLines[i]), stdin);
            trim_newline(queryLines[i]);
        }

        for (int i = 0; i < q; i++) {
            if (!firstOutput) printf("\n");
            firstOutput = 0;
            printf("%s", eval_query(queryLines[i]) ? "True" : "False");
        }
    }

    return 0;
}

