// Structure to represent a person node in the tree
struct Person {
    string name;
    Person* parent;
    vector<Person*> children;
    int depth; // depth in the tree (0 for root)

    Person(string n) : name(n), parent(nullptr), depth(0) {}
};

// Function to build the family tree from indented input
Person* buildTree(vector<string>& lines) {
    vector<pair<Person*, int>> stack; // (person, indent level)
    Person* root = nullptr;

    for (string& line : lines) {
        // Count leading spaces to determine indent level
        int indent = 0;
        while (indent < (int)line.size() && line[indent] == ' ') indent++;

        // Extract name (trim leading spaces)
        string name = line.substr(indent);

        // Create new person node
        Person* person = new Person(name);
        person->depth = indent / 2; // each indent level is 2 spaces

        // Pop stack until we find the parent
        while (!stack.empty() && stack.back().second >= person->depth) {
            stack.pop_back();
        }

        // If stack is not empty, the top is the parent
        if (!stack.empty()) {
            person->parent = stack.back().first;
            stack.back().first->children.push_back(person);
        } else {
            root = person; // root node
        }

        stack.push_back({person, person->depth});
    }

    return root;
}

// Helper function to find a person by name in the tree
Person* findPerson(Person* root, const string& name) {
    if (!root) return nullptr;
    if (root->name == name) return root;

    for (Person* child : root->children) {
        Person* found = findPerson(child, name);
        if (found) return found;
    }
    return nullptr;
}

// Check if person a is an ancestor of person b
bool isAncestor(Person* a, Person* b) {
    if (!a || !b) return false;
    Person* curr = b->parent;
    while (curr) {
        if (curr == a) return true;
        curr = curr->parent;
    }
    return false;
}

// Check if person a is a descendant of person b
bool isDescendant(Person* a, Person* b) {
    return isAncestor(b, a);
}

// Check if a is parent of b
bool isParent(Person* a, Person* b) {
    return b->parent == a;
}

// Check if a is child of b
bool isChild(Person* a, Person* b) {
    return isParent(b, a);
}

// Check if a is sibling of b (same parent)
bool isSibling(Person* a, Person* b) {
    if (!a->parent || !b->parent) return false;
    return a->parent == b->parent && a != b;
}

