/*
Assumed input format (classic indented family-tree problem):

Multiple datasets until EOF.

For each dataset:
- First line: integer N, number of lines in the family tree
- Next N lines: one person per line, with leading spaces indicating depth
- Next line: integer Q, number of statements
- Next Q lines: statements of the form
    X is child of Y
    X is parent of Y
    X is sibling of Y
    X is ancestor of Y
    X is descendant of Y

Output True / False for each statement.

Notes:
- Indentation depth is determined by the number of leading spaces.
- A child must be indented more than its parent; stack logic reconstructs the tree.
- Names are assumed to be single tokens (no spaces inside names), consistent with
  typical contest formulations.

If your judge uses a slightly different wrapper format, only the parser may need
adjustment; the relationship logic is standard.
*/

static inline int leadingSpaces(const string& s) {
    int i = 0;
    while (i < (int)s.size() && s[i] == ' ') ++i;
    return i;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    while (cin >> N) {
        string dummy;
        getline(cin, dummy); // consume endline

        vector<string> names;
        vector<int> parent;
        unordered_map<string, int> id;

        vector<pair<int,int>> st; // (indent, node id)

        for (int i = 0; i < N; ++i) {
            string line;
            getline(cin, line);

            int ind = leadingSpaces(line);
            string name = line.substr(ind);

            int cur = (int)names.size();
            names.push_back(name);
            parent.push_back(-1);
            id[name] = cur;

            while (!st.empty() && st.back().first >= ind) st.pop_back();
            if (!st.empty()) parent[cur] = st.back().second;
            st.push_back({ind, cur});
        }

        int M = (int)names.size();
        vector<vector<int>> children(M);
        for (int i = 0; i < M; ++i) {
            if (parent[i] != -1) children[parent[i]].push_back(i);
        }

        // Euler tour for ancestor queries
        vector<int> tin(M, -1), tout(M, -1);
        int timer = 0;
        function<void(int)> dfs = [&](int u) {
            tin[u] = timer++;
            for (int v : children[u]) dfs(v);
            tout[u] = timer++;
        };
        for (int i = 0; i < M; ++i) {
            if (parent[i] == -1) dfs(i);
        }

        auto isAncestor = [&](int a, int b) -> bool {
            if (a < 0 || b < 0) return false;
            return tin[a] <= tin[b] && tout[b] <= tout[a] && a != b;
        };

        int Q;
        cin >> Q;
        getline(cin, dummy);

        for (int qi = 0; qi < Q; ++qi) {
            string s;
            getline(cin, s);

            stringstream ss(s);
            string A, isword, rel, ofword, B;
            ss >> A >> isword >> rel >> ofword >> B;

            bool ans = false;

            if (!id.count(A) || !id.count(B)) {
                ans = false;
            } else {
                int a = id[A], b = id[B];

                if (rel == "child") {
                    ans = (parent[a] == b);
                } else if (rel == "parent") {
                    ans = (parent[b] == a);
                } else if (rel == "sibling") {
                    ans = (a != b && parent[a] != -1 && parent[a] == parent[b]);
                } else if (rel == "ancestor") {
                    ans = isAncestor(a, b);
                } else if (rel == "descendant") {
                    ans = isAncestor(b, a);
                } else {
                    ans = false;
                }
            }

            cout << (ans ? "True" : "False") << '\n';
        }
    }

    return 0;
}

import sys

def solve():
    data = sys.stdin.read().splitlines()
    i = 0
    out_lines = []
    while i < len(data):
        # Skip empty lines before a dataset
        while i < len(data) and data[i].strip() == '':
            i += 1
        if i >= len(data):
            break
        # Parse tree
        parent = {}
        children = {}
        depth_stack = []  # stack of (name, depth)
        while i < len(data):
            line = data[i]
            if line.strip() == '':
                i += 1
                break
            name = line.strip()
            depth = len(line) - len(line.lstrip())
            # Pop stack until we find parent
            while depth_stack and depth_stack[-1][1] >= depth:
                depth_stack.pop()
            if depth_stack:
                par = depth_stack[-1][0]
                parent[name] = par
                children.setdefault(par, []).append(name)
            else:
                parent[name] = None  # root
            children.setdefault(name, [])
            depth_stack.append((name, depth))
            i += 1
        # Now parse statements
        while i < len(data) and data[i].strip() == '':
            i += 1
        while i < len(data) and data[i].strip() != '':
            stmt = data[i].strip()
            i += 1
            # Parse statement: "X is a ... of Y"
            parts = stmt.split()
            if len(parts) < 5:
                continue
            x = parts[0]
            y = parts[-1]
            rel = ' '.join(parts[2:-1])  # e.g., "a parent", "an ancestor", etc.
            # Normalize relation
            rel = rel.replace('a ', '').replace('an ', '')
            # Evaluate
            res = False
            if rel == 'parent':
                res = parent.get(y) == x
            elif rel == 'child':
                res = parent.get(x) == y
            elif rel == 'ancestor':
                # BFS/DFS from x to see if y is descendant
                stack = [x]
                visited = set()
                while stack:
                    cur = stack.pop()
                    if cur == y:
                        res = True
                        break
                    for child in children.get(cur, []):
                        if child not in visited:
                            visited.add(child)
                            stack.append(child)
            elif rel == 'descendant':
                # same as ancestor(y, x)
                stack = [y]
                visited = set()
                while stack:
                    cur = stack.pop()
                    if cur == x:
                        res = True
                        break
                    for child in children.get(cur, []):
                        if child not in visited:
                            visited.add(child)
                            stack.append(child)
            elif rel == 'sibling':
                res = (parent.get(x) is not None and parent.get(x) == parent.get(y) and x != y)
            elif rel == 'cousin':
                # same depth, parents are siblings
                if x in parent and y in parent and parent[x] and parent[y]:
                    px = parent[x]
                    py = parent[y]
                    if px != py:
                        # check if px and py are siblings
                        res = (parent.get(px) is not None and parent.get(px) == parent.get(py))
            elif rel == 'grandparent':
                res = (parent.get(y) is not None and parent.get(parent.get(y)) == x)
            elif rel == 'grandchild':
                res = (parent.get(x) is not None and parent.get(parent.get(x)) == y)
            elif rel == 'uncle' or rel == 'aunt':
                # sibling of parent
                p = parent.get(y)
                if p is not None and parent.get(x) is not None:
                    res = (parent.get(x) == parent.get(p) and x != p)
            elif rel == 'nephew' or rel == 'niece':
                # child of sibling
                p = parent.get(x)
                if p is not None and parent.get(y) is not None:
                    res = (parent.get(p) == parent.get(y) and p != y)
            out_lines.append('True' if res else 'False')
    sys.stdout.write('\n'.join(out_lines))

if __name__ == '__main__':
    solve()

